CREATE TABLE IF NOT EXISTS bookkeeping_batch_revisions (
  id INTEGER PRIMARY KEY,
  run_id INTEGER NOT NULL REFERENCES bookkeeping_batch_runs(id),
  revision_hash TEXT NOT NULL CHECK(length(revision_hash)=64),
  candidate_set_hash TEXT NOT NULL CHECK(length(candidate_set_hash)=64),
  plan_json TEXT NOT NULL,
  planner_kind TEXT NOT NULL CHECK(planner_kind IN ('user','service-account','local-trusted')),
  planner_subject_id TEXT NOT NULL,
  planner_actor TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(run_id, revision_hash)
);
CREATE TABLE IF NOT EXISTS bookkeeping_batch_revision_approvals (
  id INTEGER PRIMARY KEY,
  revision_id INTEGER NOT NULL REFERENCES bookkeeping_batch_revisions(id),
  principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service-account','local-trusted')),
  principal_subject_id TEXT NOT NULL,
  actor TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(revision_id, principal_kind, principal_subject_id)
);
CREATE TABLE IF NOT EXISTS bookkeeping_batch_apply_attempts_v2 (
  id INTEGER PRIMARY KEY,
  revision_id INTEGER NOT NULL REFERENCES bookkeeping_batch_revisions(id),
  plan_hash TEXT NOT NULL CHECK(length(plan_hash)=64),
  principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service-account','local-trusted')),
  principal_subject_id TEXT NOT NULL,
  actor TEXT NOT NULL,
  started_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS bookkeeping_batch_apply_events_v2 (
  id INTEGER PRIMARY KEY,
  apply_attempt_id INTEGER NOT NULL REFERENCES bookkeeping_batch_apply_attempts_v2(id),
  event_type TEXT NOT NULL CHECK(event_type IN ('started','source_stale','item_applied','item_failed','final_checks','completed')),
  action_key TEXT,
  detail_json TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS bookkeeping_batch_final_checks_v2 (
  id INTEGER PRIMARY KEY,
  apply_attempt_id INTEGER NOT NULL REFERENCES bookkeeping_batch_apply_attempts_v2(id),
  check_name TEXT NOT NULL CHECK(check_name IN ('audit_chain','trial_balance','reconciliation','vat')),
  ok INTEGER NOT NULL CHECK(ok IN (0,1)),
  detail_json TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(apply_attempt_id,check_name)
);
CREATE INDEX IF NOT EXISTS idx_batch_revisions_run ON bookkeeping_batch_revisions(run_id,id);
CREATE INDEX IF NOT EXISTS idx_batch_approval_revision ON bookkeeping_batch_revision_approvals(revision_id,id);
CREATE INDEX IF NOT EXISTS idx_batch_attempts_revision ON bookkeeping_batch_apply_attempts_v2(revision_id,id);
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_revisions_no_update BEFORE UPDATE ON bookkeeping_batch_revisions BEGIN SELECT RAISE(ABORT, 'bookkeeping batch revisions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_revisions_no_delete BEFORE DELETE ON bookkeeping_batch_revisions BEGIN SELECT RAISE(ABORT, 'bookkeeping batch revisions are append-only'); END;
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_revision_approvals_no_update BEFORE UPDATE ON bookkeeping_batch_revision_approvals BEGIN SELECT RAISE(ABORT, 'bookkeeping batch approvals are immutable'); END;
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_revision_approvals_no_delete BEFORE DELETE ON bookkeeping_batch_revision_approvals BEGIN SELECT RAISE(ABORT, 'bookkeeping batch approvals are append-only'); END;
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_apply_attempts_v2_no_update BEFORE UPDATE ON bookkeeping_batch_apply_attempts_v2 BEGIN SELECT RAISE(ABORT, 'bookkeeping batch attempts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_apply_attempts_v2_no_delete BEFORE DELETE ON bookkeeping_batch_apply_attempts_v2 BEGIN SELECT RAISE(ABORT, 'bookkeeping batch attempts are append-only'); END;
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_apply_events_v2_no_update BEFORE UPDATE ON bookkeeping_batch_apply_events_v2 BEGIN SELECT RAISE(ABORT, 'bookkeeping batch apply events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_apply_events_v2_no_delete BEFORE DELETE ON bookkeeping_batch_apply_events_v2 BEGIN SELECT RAISE(ABORT, 'bookkeeping batch apply events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_final_checks_v2_no_update BEFORE UPDATE ON bookkeeping_batch_final_checks_v2 BEGIN SELECT RAISE(ABORT, 'bookkeeping batch final checks are immutable'); END;
CREATE TRIGGER IF NOT EXISTS bookkeeping_batch_final_checks_v2_no_delete BEFORE DELETE ON bookkeeping_batch_final_checks_v2 BEGIN SELECT RAISE(ABORT, 'bookkeeping batch final checks are append-only'); END;
